assign spi0_clk = ((spicsr0_spicsr0_clk & (~spicsr0_spicsr0_done0)) ^ spicsr0_spicsr0_mode[1]);
always @(*) begin
    spicsr0_spicsr0_clk_even <= 1'd0;
    spicsr0_spicsr0_clk_odd <= 1'd0;
    if (spicsr0_spicsr0_clk_enable) begin
        spicsr0_spicsr0_clk_odd <= (spicsr0_spicsr0_clk & (~spicsr0_spicsr0_clk_d));
        spicsr0_spicsr0_clk_even <= ((~spicsr0_spicsr0_clk) & spicsr0_spicsr0_clk_d);
    end
end
always @(*) begin
    spicsr0_spicsr0_mosi_shift <= 1'd0;
    case (spicsr0_spicsr0_mode[0])
        1'd0: begin
            spicsr0_spicsr0_mosi_shift <= spicsr0_spicsr0_clk_even;
        end
        1'd1: begin
            spicsr0_spicsr0_mosi_shift <= (spicsr0_spicsr0_clk_odd & spicsr0_spicsr0_clk_run);
        end
    endcase
end
assign spi0_mosi = spicsr0_spicsr0_mosi_data[31];
always @(*) begin
    spicsr0_spicsr0_miso_shift <= 1'd0;
    case (spicsr0_spicsr0_mode[0])
        1'd0: begin
            spicsr0_spicsr0_miso_shift <= spicsr0_spicsr0_clk_odd;
        end
        1'd1: begin
            spicsr0_spicsr0_miso_shift <= spicsr0_spicsr0_clk_even;
        end
    endcase
end
always @(*) begin
    spicsr0_spicsr0_miso1 <= 1'd0;
    case (spicsr0_spicsr0_loopback)
        1'd0: begin
            spicsr0_spicsr0_miso1 <= spi0_miso;
        end
        1'd1: begin
            spicsr0_spicsr0_miso1 <= spi0_mosi;
        end
    endcase
end
assign spicsr0_spicsr0_miso0 = spicsr0_spicsr0_miso_data;
assign spicsr0_spicsr0_loopback = spicsr0_csrfield_loopback;
