assign spicsr0_spicsr0_cs = spicsr0_csrfield_cs;
assign spicsr0_spicsr0_done1 = (spicsr0_spicsr0_count == 1'd0);
always @(*) begin
    frontendcontrolaxi_fsm0_next_state <= 2'd0;
    frontendcontrolaxi_fsm1_next_state <= 1'd0;
